"""Three fresh-browser normal-play DOM-pointer-to-position probes; never OS-input timing."""
import argparse,json,time
from pathlib import Path
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('--out',type=Path,required=True);a=p.parse_args();a.out.mkdir(exist_ok=True,parents=True);rows=[]
with sync_playwright() as pw:
 for name,port,sha in [('before',8013,'7faa21a274847ca649a7a96b88700d4cdda5fe2e'),('rally',8012,'91569e206d08c8b0e8af2f071d838aa1b66eb0e8'),('civ',8010,'dc4698a3f8801ea5ada37a908951900fca6a8ef6')]:
  for rep in range(3):
   b=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);page=b.new_page(viewport={'width':1600,'height':1100});page.goto(f'http://127.0.0.1:{port}');page.wait_for_function('!!window.ageOfAsh');m=page.request.get(f'http://127.0.0.1:{port}/__qa_build.json').json();assert m['commit']==sha and not m['dirty'];page.locator('#setup-civ').select_option('TEU');page.locator('#setup-seed').fill('riftwatch-p0-v1');page.locator('#btn-start').click();page.wait_for_timeout(150)
   origin=page.evaluate("()=>{const g=ageOfAsh.game,u=g.units.find(u=>u.type==='light_cavalry'),p=ageOfAsh.renderer.screen(g,u.x,u.y);return {id:u.id,x:p.x,y:p.y-18*g.camera.zoom};}");page.mouse.click(origin['x'],origin['y']);assert page.evaluate('(id)=>ageOfAsh.game.selection.some(u=>u.id===id)',origin['id'])
   destination=page.evaluate('''id=>{const g=ageOfAsh.game,u=g.units.find(u=>u.id===id);window.inputAudit={origin:{x:u.x,y:u.y},event:null,handler:null,response:null,id};document.querySelector('#game').addEventListener('pointerdown',e=>{if(e.button===2){inputAudit.event=e.timeStamp;inputAudit.handler=performance.now();}},{capture:true});function observe(){if(inputAudit.event!==null&&Math.hypot(u.x-inputAudit.origin.x,u.y-inputAudit.origin.y)>.005){inputAudit.response=performance.now();return;}requestAnimationFrame(observe);}requestAnimationFrame(observe);return ageOfAsh.renderer.screen(g,32,29);}''',origin['id']);start=time.monotonic();page.mouse.click(destination['x'],destination['y'],button='right');page.wait_for_function('inputAudit.response!==null',timeout=5000);wall=(time.monotonic()-start)*1000;data=page.evaluate('()=>inputAudit');rows.append({'branch':name,'rep':rep+1,'commit':sha,'scope':'normal starting scene, DOM event timestamp to observed movement; excludes hardware/OS latency','dom_to_movement_ms':data['response']-data['event'],'handler_to_movement_ms':data['response']-data['handler'],'agent_roundtrip_upper_bound_ms':wall,'pass':data['response']-data['event']<=250});b.close()
(a.out/'results.json').write_text(json.dumps(rows,indent=2));print(rows)
